const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], t=k=>copy[language][k];
function card(p){return `<button class="project-card ${p.id} ${p.cover?'has-media':''}" data-project="${p.id}" aria-label="${t('viewCase')}: ${p.title}">${p.cover?`<img class="case-thumbnail" src="${p.cover}" alt="" loading="lazy">`:''}<div><h3>${p.title}</h3><p class="card-description">${p[language].teaser}</p></div><div class="card-bottom"><span>${p.media.length?[['video',language==='pt'?'vídeos':'videos'],['image',language==='pt'?'imagens':'images']].map(([type,label])=>{const n=p.media.filter(m=>m.type===type).length;return n?`${n} ${label}`:''}).filter(Boolean).join(' / '):t('viewCase')}</span><span class="card-arrow" aria-hidden="true">↗</span></div></button>`}
function renderCatalog(){const selected=projects.filter(p=>filter==='all'||p.categories.includes(filter));$('#catalog-track').innerHTML=selected.map(card).join('');$('#catalog-count').textContent=`${String(selected.length).padStart(2,'0')} ${t('count')}`;$('#filters').innerHTML=['all','video','photo','social','identity'].map(k=>`<button data-filter="${k}" aria-pressed="${filter===k}">${t(k)}</button>`).join('');requestAnimationFrame(updateArrows)}
function mediaTitle(m){return language==='en'?(m.en||m.name):(m.pt||m.name)}
function pauseCaseVideos(){ $$('#project-dialog video').forEach(v=>v.pause()) }
function renderProject(){if(!activeProject)return;pauseCaseVideos();const p=activeProject,images=p.media.filter(m=>m.type==='image'),videos=p.media.filter(m=>m.type==='video');$('#project-content').innerHTML=`<div class="project-cover ${p.id} ${p.cover?'has-media':''}">${p.cover?`<img class="case-thumbnail" src="${p.cover}" alt="">`:''}<h2 id="project-title">${p.title}</h2><p>${p.categories.map(c=>t(c)).join(' / ')}</p></div><div class="project-details">${p[language].challenge?`<div><h3>${t('challenge')}</h3><p>${p[language].challenge}</p></div><div><h3>${t('result')}</h3><p>${p[language].result}</p></div>`:`<p class="full">${p[language].teaser}</p>`}</div>${videos.length?`<section class="case-media-section"><h3>${t('caseVideos')}</h3><div class="case-video-grid">${videos.map(m=>`<figure><video controls playsinline preload="none" poster="${m.poster}" aria-label="${p.title}: ${mediaTitle(m)}" data-src="${m.src}"><source src="${m.src}" type="video/mp4"></video><figcaption>${mediaTitle(m)}</figcaption><p class="media-error" hidden>${t('videoError')} <a href="${m.src}" target="_blank" rel="noopener">${t('openVideo')}</a></p></figure>`).join('')}</div></section>`:''}${images.length?`<section class="case-media-section"><h3>${t('caseImages')}</h3><div class="case-image-grid">${images.map((m,i)=>`<button class="case-image" data-case-photo="${i}" aria-label="${p.title}: ${mediaTitle(m)}"><img src="${m.src}" alt="${p.title}: ${mediaTitle(m)}" width="${m.width}" height="${m.height}" loading="lazy"><span>${mediaTitle(m)} <span aria-hidden="true">↗</span></span></button>`).join('')}</div></section>`:''}<div class="case-footer"><button class="text-link" id="project-contact" style="background:none"><span>${t('startProject')}</span><span aria-hidden="true">↗</span></button></div>`;$$('#project-dialog video').forEach(v=>{v.addEventListener('play',()=>$$('#project-dialog video').forEach(other=>{if(other!==v)other.pause()}));v.addEventListener('error',()=>{v.closest('figure').querySelector('.media-error').hidden=false})})}
function renderPhoto(){const list=lightboxItems||photos,p=list[photoIndex];$('#lightbox-image').src=p.src||`./assets/portrait-${p.file}.webp`;$('#lightbox-image').alt=p.src?`${activeProject.title}: ${mediaTitle(p)}`:p[language==='pt'?'altPt':'altEn'];$('#lightbox-title').textContent=p.src?mediaTitle(p):p[language];$('#photo-position').textContent=`${photoIndex+1} / ${list.length}`}
function translate(){document.documentElement.lang=language==='pt'?'pt-BR':'en';$$('[data-t]').forEach(el=>el.innerHTML=t(el.dataset.t));$$('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.lang===language));$('#featured-grid').innerHTML=projects.filter(p=>['gross','rocco','affinita'].includes(p.id)).map(card).join('');renderCatalog();$('#photo-gallery').innerHTML=photos.map((p,i)=>`<button class="photo-card" data-photo="${i}" aria-label="${p[language]}"><img src="./assets/portrait-${p.file}.webp" alt="${p[language==='pt'?'altPt':'altEn']}" width="2000" height="1116" loading="lazy"><span>${p[language]}</span></button>`).join('');const openServices=$$('#services details').map((e,i)=>e.open?i:-1);$('#services').innerHTML=services.map((s,i)=>`<details class="service" ${openServices.includes(i)?'open':''}><summary><h3>${s[language][0]}${i===4?`<span class="free-badge">${t('free')}</span>`:''}</h3></summary><p>${s[language][1]}</p></details>`).join('');const selectedService=$('#service-select').value;$('#service-select').innerHTML=services.map((s,i)=>`<option value="${i}">${s[language][0]}</option>`).join('');if(selectedService)$('#service-select').value=selectedService;$$('[data-close]').forEach(e=>e.setAttribute('aria-label',t('close')));$('#catalog-prev').setAttribute('aria-label',t('prev'));$('#catalog-next').setAttribute('aria-label',t('next'));$('#photo-prev').setAttribute('aria-label',t('photoPrev'));$('#photo-next').setAttribute('aria-label',t('photoNext'));$('.menu-toggle').setAttribute('aria-label',t('menu'));$('#filters').setAttribute('aria-label',t('categories'));$('#catalog-track').setAttribute('aria-label',t('catalogAria'));$('.hero-image').alt=language==='pt'?'William Borella em retrato com iluminação laranja':'Portrait of William Borella with orange lighting';$('.about-image img').alt=language==='pt'?'William Borella ao ar livre sob a luz do sol':'William Borella outdoors in sunlight';$('#form-status').textContent='';renderProject();renderPhoto();document.title=language==='pt'?'William Borella — Histórias que fazem sua marca ser vista':'William Borella — Stories that get your brand seen';$('meta[name="description"]').content=language==='pt'?'Videomaking, fotografia e gestão de redes sociais com William Borella. Conheça os projetos e uma visão direta, criativa e humana para a sua marca.':'Filmmaking, photography and social media with William Borella. Explore the projects and a direct, creative and human vision for your brand.'}
function openDialog(id){$(id).showModal();if(id==='#project-dialog')$('#project-content').scrollTop=0;document.body.classList.add('modal-open')}
function closeDialog(dialog){dialog.close();if(!$$('dialog').some(d=>d.open))document.body.classList.remove('modal-open')}
function movePhoto(direction){const length=(lightboxItems||photos).length;photoIndex=(photoIndex+direction+length)%length;renderPhoto()}
function updateArrows(){const el=$('#catalog-track');$('#catalog-prev').disabled=el.scrollLeft<3;$('#catalog-next').disabled=el.scrollLeft+el.clientWidth>=el.scrollWidth-3}
document.addEventListener('click',e=>{const lang=e.target.closest('[data-lang]');if(lang){language=lang.dataset.lang;try{localStorage.setItem('borella-language',language)}catch{}translate()}const project=e.target.closest('[data-project]');if(project){activeProject=projects.find(p=>p.id===project.dataset.project);renderProject();openDialog('#project-dialog')}const photo=e.target.closest('[data-photo]');if(photo){lightboxItems=null;photoIndex=Number(photo.dataset.photo);renderPhoto();openDialog('#lightbox')}const casePhoto=e.target.closest('[data-case-photo]');if(casePhoto){pauseCaseVideos();lightboxItems=activeProject.media.filter(m=>m.type==='image');photoIndex=Number(casePhoto.dataset.casePhoto);renderPhoto();openDialog('#lightbox')}const filterButton=e.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;renderCatalog();$(`[data-filter="${filter}"]`).focus()}const close=e.target.closest('[data-close]');if(close)closeDialog(close.closest('dialog'));if(e.target.closest('#project-contact')){closeDialog($('#project-dialog'));openDialog('#contact-dialog')}});
$$('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(dialog)}});dialog.addEventListener('close',()=>{if(dialog.id==='project-dialog')pauseCaseVideos();if(!$$('dialog').some(d=>d.open))document.body.classList.remove('modal-open')})});
$('#lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();movePhoto(1)}if(e.key==='ArrowLeft'){e.preventDefault();movePhoto(-1)}});$('#photo-prev').onclick=()=>movePhoto(-1);$('#photo-next').onclick=()=>movePhoto(1);$('#contact-open').onclick=()=>openDialog('#contact-dialog');
for(const [id,direction] of [['#catalog-prev',-1],['#catalog-next',1]])$(id).onclick=()=>$('#catalog-track').scrollBy({left:direction*$('#catalog-track').clientWidth*.75,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#catalog-track').addEventListener('scroll',updateArrows,{passive:true});window.addEventListener('resize',updateArrows);
$('.menu-toggle').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open)};$$('#navigation a').forEach(a=>a.onclick=()=>{$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#navigation').classList.contains('open')){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').focus()}});
const updateHeader=()=>$('.header').classList.toggle('fixed',scrollY>100);window.addEventListener('scroll',updateHeader,{passive:true});window.addEventListener('pageshow',updateHeader);updateHeader();
$('#contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target),body=[`William Borella — ${language==='pt'?'Briefing':'Project brief'}`,...['name','company','phone','email'].map(k=>`${t(k)}: ${data.get(k)}`),`${t('interest')}: ${services[Number(data.get('service'))][language][0]}`].join('\n');const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='briefing-borella.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#form-status').textContent=t('briefSaved')});
$('#year').textContent=new Date().getFullYear();translate();
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});$$('.section-heading,.about-copy,.contact h2').forEach(e=>{e.classList.add('reveal');observer.observe(e)});const navObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)$$('#navigation a').forEach(a=>a.classList.toggle('active',a.hash===`#${entry.target.id}`))})},{rootMargin:'-20% 0px -60% 0px'});$$('main section[id]').forEach(s=>navObserver.observe(s))}
